param([string]$ProjectRoot="C:\Dev\chris")
$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "CHRIS 2G.2A6W - Payment Details Bank Verification" -ForegroundColor Green

$component = Join-Path $ProjectRoot "src\components\employees\OnboardingSectionDataForm.jsx"
$routes = Join-Path $ProjectRoot "backend\src\routes\onboardingRoutes.js"

foreach($file in @($component,$routes)){
  if(!(Test-Path $file)){
    throw "Required file missing: $file"
  }
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $ProjectRoot ".chris-backups\sprint-2g2a6w-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null

Copy-Item $component (Join-Path $backup "OnboardingSectionDataForm.jsx") -Force
Copy-Item $routes (Join-Path $backup "onboardingRoutes.js") -Force

Write-Host ""
Write-Host "=== 1. INSTALL PAYMENT DETAILS UI ===" -ForegroundColor Cyan

$componentContent =
  [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
  )

[IO.File]::WriteAllText(
  $component,
  $componentContent,
  [Text.UTF8Encoding]::new($false)
)

Write-Host "PASS: Bank dropdown and automatic account-name verification UI installed." -ForegroundColor Green

Write-Host ""
Write-Host "=== 2. INSTALL BANK LOOKUP API ROUTES ===" -ForegroundColor Cyan

$r = [IO.File]::ReadAllText($routes)

if($r -notmatch '"/payment/resolve-account"'){
  $anchor = 'router.post(' + "`r`n" + '  "/:employeeNumber",'

  $idx = $r.IndexOf($anchor)

  if($idx -lt 0){
    $anchor = 'router.post(' + "`n" + '  "/:employeeNumber",'
    $idx = $r.IndexOf($anchor)
  }

  if($idx -lt 0){
    throw "Start-onboarding POST route anchor not found."
  }

  $snippet =
    [Text.Encoding]::UTF8.GetString(
      [Convert]::FromBase64String("")
    )

  $r = $r.Insert(
    $idx,
    $snippet
  )

  [IO.File]::WriteAllText(
    $routes,
    $r,
    [Text.UTF8Encoding]::new($false)
  )

  Write-Host "PASS: Bank list and account resolve routes inserted before /:employeeNumber." -ForegroundColor Green
}
else{
  Write-Host "OK: Payment bank verification routes already present." -ForegroundColor DarkGreen
}

Write-Host ""
Write-Host "=== 3. BACKEND SYNTAX CHECK ===" -ForegroundColor Cyan

Push-Location (Join-Path $ProjectRoot "backend")
try{
  node --check src\routes\onboardingRoutes.js
  if($LASTEXITCODE -ne 0){
    throw "Backend syntax check failed."
  }
}
finally{
  Pop-Location
}

Write-Host "PASS: Backend syntax valid." -ForegroundColor Green

Write-Host ""
Write-Host "=== 4. ASCII SOURCE SAFETY ===" -ForegroundColor Cyan

foreach($file in @($component,$routes)){
  $bytes = [IO.File]::ReadAllBytes($file)
  $bad = 0

  foreach($byte in $bytes){
    if($byte -gt 127){
      $bad++
    }
  }

  if($bad -gt 0){
    throw "$file contains $bad non-ASCII source bytes."
  }

  Write-Host "PASS: ASCII-safe source - $file" -ForegroundColor Green
}

Write-Host ""
Write-Host "=== 5. FRONTEND BUILD ===" -ForegroundColor Cyan

Push-Location $ProjectRoot
try{
  npm run build

  if($LASTEXITCODE -ne 0){
    throw "Frontend build failed."
  }
}
finally{
  Pop-Location
}

Write-Host ""
Write-Host "============================================================"
Write-Host "CHRIS 2G.2A6W - PAYMENT DETAILS BANK VERIFICATION PASSED" -ForegroundColor Green
Write-Host "============================================================"
Write-Host ""
Write-Host "Delivered:"
Write-Host "  Bank Name is a dropdown."
Write-Host "  Bank list loads from Paystack when configured, with a Nigerian fallback list."
Write-Host "  Account Number accepts digits only and stops at 10 digits."
Write-Host "  Selecting a bank + entering 10 digits triggers account-name verification."
Write-Host "  Account Name is read-only and populated from the bank verification response."
Write-Host ""
Write-Host "IMPORTANT:"
Write-Host "  Automatic account-name resolution requires PAYSTACK_SECRET_KEY in backend\.env."
Write-Host "  Keep this secret only in the backend environment. Never put it in frontend code."
Write-Host ""
Write-Host "Backup: $backup"